select coalesce(sum(transfer_amount), 0) from `order`
WHERE created_at >= #{startDatetime}
  AND created_at <= #{endDatetime} and status = 9

        AND merchant_id = #{shopId}

SELECT coalesce(SUM(fiat_amount), 0)
FROM `order`
WHERE created_at >= #{startDatetime}
  AND created_at <= #{endDatetime}
  AND status = 9

    AND merchant_id = #{shopId}

SELECT

    (SELECT COALESCE(SUM(transfer_amount), 0) FROM `order`
    WHERE created_at >= #{range.startDatetime}
    AND CONVERT_TZ(created_at, '+00:00', '+08:00') <= #{range.endDatetime}
    AND status = 9

        AND merchant_id = #{shopId}

    )

SELECT DATE(created_at) as date, status, COUNT(1) as count FROM `order` WHERE CONVERT_TZ(created_at, '+00:00', '+08:00') >= #{startDate} AND CONVERT_TZ(created_at, '+00:00', '+08:00') <= concat(#{endDate}, ' 23:59:59') and status in (4,5,6,7,9,17)
AND merchant_id = #{shopId}
GROUP BY DATE(created_at), status ORDER BY date, status

SELECT DATE(created_at) as date, status, coalesce(SUM(transfer_amount),0) as amount FROM `order` WHERE CONVERT_TZ(created_at, '+00:00', '+08:00') >= #{startDate} AND CONVERT_TZ(created_at, '+00:00', '+08:00') <= concat(#{endDate}, ' 23:59:59') and status in (4,5,6,7,9,17)
AND merchant_id = #{shopId}
GROUP BY DATE(created_at), status ORDER BY date, status

SELECT DATE(CONVERT_TZ(created_at, '+00:00', '+08:00')) as date, coalesce(ROUND(AVG(transfer_amount), 2), 0) as amount FROM `order` WHERE created_at >= CONVERT_TZ(concat(#{startDate}, ' 00:00:00'), '+08:00', '+00:00') AND created_at < CONVERT_TZ(DATE_ADD(concat(#{endDate}, ' 00:00:00'), INTERVAL 1 DAY), '+08:00', '+00:00') AND status = 9
AND merchant_id = #{shopId}
GROUP BY DATE(CONVERT_TZ(created_at, '+00:00', '+08:00')) ORDER BY date

SELECT
coalesce(ROUND(AVG(transfer_amount), 2), 0)
FROM `order`
WHERE created_at >= #{startDatetime}
AND created_at <= #{endDatetime}
AND status = 9

    AND merchant_id = #{shopId}

SELECT

    (SELECT COALESCE(ROUND(AVG(transfer_amount), 2), 0)
    FROM `order`
    WHERE created_at >= #{range.startDatetime}
    AND created_at <= #{range.endDatetime}
    AND status = 9

        AND merchant_id = #{shopId}

    )

SELECT payment_type as type, COUNT(*) as count FROM `order` WHERE created_at >= CONVERT_TZ(concat(#{startDate}, ' 00:00:00'), '+08:00', '+00:00') AND created_at < CONVERT_TZ(DATE_ADD(concat(#{endDate}, ' 00:00:00'), INTERVAL 1 DAY), '+08:00', '+00:00') AND status in (5,6,9,17)
AND merchant_id = #{shopId}
GROUP BY payment_type ORDER BY count DESC

SELECT cct.card_brand as type, COUNT(distinct o.id) as count FROM `order` o JOIN customer c ON o.customer_id = c.id JOIN customer_card_token cct ON c.user_id = cct.user_id WHERE o.created_at >= CONVERT_TZ(concat(#{startDate}, ' 00:00:00'), '+08:00', '+00:00') AND o.created_at < CONVERT_TZ(DATE_ADD(concat(#{endDate}, ' 00:00:00'), INTERVAL 1 DAY), '+08:00', '+00:00') AND o.payment_type = 'card'
AND o.merchant_id = #{shopId}
GROUP BY cct.card_brand ORDER BY count DESC

SELECT
    CONCAT(DATE_FORMAT(created_at, '%m-%d'), ' ', LPAD(HOUR(created_at), 2, '0')) as date,
    status,
    COUNT(1) as count
FROM `order`
WHERE created_at >= #{startDatetime}
AND created_at <= #{endDatetime}

    AND merchant_id = #{shopId}

GROUP BY DATE(created_at), HOUR(created_at), status
ORDER BY created_at, status

SELECT fail_reasons as failReason, COUNT(*) as count FROM `order` WHERE fail_reasons IS NOT NULL AND fail_reasons != '' AND status IN (4, 5, 6, 7, 17, 20, 30, 40)
AND created_at >= #{startDate}
AND created_at <= #{endDate}
AND merchant_id = #{shopId}
GROUP BY fail_reasons ORDER BY count DESC LIMIT 100
